interface SplitMatchProps {
  /**
   * Words in order; the reels lock on each one, the last one is the poster.
   * "remocn" is set as the real logo (R mark + "emocn" in Manrope).
   */
  words?: string[];
  accent?: string;
  /** Text color of the stage-side words; overrides the theme ink. */
  ink?: string;
  /** Background fill; "transparent" drops it. */
  background?: string;
  /** Typeface for the words. Load it yourself; Bricolage Grotesque by default. */
  fontFamily?: string;
  /** Frames each word stays locked before the reels move on. */
  hold?: number;
  /** Frames for the reels to travel from one word to the next. */
  step?: number;
  /** Size of the split and panel, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  grain?: boolean;
  theme?: "dark" | "light";
  speed?: number;
}

// Beat sheet (30fps), four words:
//  0–10    both reels slam in from opposite sides and lock on word 1
//  10–26   hold: left half on stage, right half on a gradient panel, one word
//  26–35   step: left reel climbs, right reel drops, halves blur past each other
//  ...     two more step + lock beats
//  85      final lock on the last word
//  93–109  the seam closes: the gradient floods the left panel, neighbours fall away
//  109–145 poster hold with a slow push
const ENTER = 10;
const HOLD = 16;
const STEP = 9;
const MERGE_DELAY = 8;
const MERGE = 16;
const TAIL = 36;

function splitMatchDuration(wordCount = 4, hold = HOLD, step = STEP) {
  return (
    ENTER +
    Math.max(0, wordCount - 1) * (hold + step) +
    MERGE_DELAY +
    MERGE +
    TAIL
  );
}

